mkuse!{use rustc_index :: IndexVec ;}
mkuse!{use rustc_middle :: mir :: { BasicBlock , Body , Location } ;}
mkuse!{use tracing :: debug ;}
mkitem!{mkstruct!{# [doc = " Maps between a MIR Location, which identifies a particular"] # [doc = " statement within a basic block, to a \"rich location\", which"] # [doc = " identifies at a finer granularity. In particular, we distinguish"] # [doc = " the *start* of a statement and the *mid-point*. The mid-point is"] # [doc = " the point *just* before the statement takes effect; in particular,"] # [doc = " for an assignment `A = B`, it is the point where B is about to be"] # [doc = " written into A. This mid-point is a kind of hack to work around"] # [doc = " our inability to track the position information at sufficient"] # [doc = " granularity through outlives relations; however, the rich location"] # [doc = " table serves another purpose: it compresses locations from"] # [doc = " multiple words into a single u32."] pub struct PoloniusLocationTable { num_points : usize , statements_before_block : IndexVec < BasicBlock , usize > , }}}
mkitem!{rustc_index :: newtype_index ! { # [orderable] # [debug_format = "LocationIndex({})"] pub struct LocationIndex { } }}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug)] pub enum RichLocation { Start (Location) , Mid (Location) , }}}
mkitem!{mkimpl!{impl PoloniusLocationTable { pub (crate) fn new (body : & Body < '_ >) -> Self { let mut num_points = 0 ; let statements_before_block = body . basic_blocks . iter () . map (| block_data | { let v = num_points ; num_points += (block_data . statements . len () + 1) * 2 ; v }) . collect () ; debug ! ("PoloniusLocationTable(statements_before_block={:#?})" , statements_before_block) ; debug ! ("PoloniusLocationTable: num_points={:#?}" , num_points) ; Self { num_points , statements_before_block } } pub fn all_points (& self) -> impl Iterator < Item = LocationIndex > { (0 .. self . num_points) . map (LocationIndex :: from_usize) } pub fn start_index (& self , location : Location) -> LocationIndex { let Location { block , statement_index } = location ; let start_index = self . statements_before_block [block] ; LocationIndex :: from_usize (start_index + statement_index * 2) } pub fn mid_index (& self , location : Location) -> LocationIndex { let Location { block , statement_index } = location ; let start_index = self . statements_before_block [block] ; LocationIndex :: from_usize (start_index + statement_index * 2 + 1) } pub fn to_rich_location (& self , index : LocationIndex) -> RichLocation { let point_index = index . index () ; let (block , & first_index) = self . statements_before_block . iter_enumerated () . rfind (| & (_ , & first_index) | first_index <= point_index) . unwrap () ; let statement_index = (point_index - first_index) / 2 ; if index . is_start () { RichLocation :: Start (Location { block , statement_index }) } else { RichLocation :: Mid (Location { block , statement_index }) } } pub fn to_location (& self , index : LocationIndex) -> Location { match self . to_rich_location (index) { RichLocation :: Start (location) => location , RichLocation :: Mid (location) => location , } } }}}
mkitem!{mkimpl!{impl LocationIndex { fn is_start (self) -> bool { self . index () . is_multiple_of (2) } }}}